// Example: pick a model based on policy
function selectModel(tenant, policy) {
  const p = policy[tenant] || {};
  if (p.forceGuard) return 'safety-guarded';
  if (p.latencyBudget && p.latencyBudget < 75) return 'base';
  return p.preferredModel ?? 'base';
}
```

